import org.testng.Assert;
import org.testng.annotations.Test;
import org.testng.asserts.SoftAssert;

public class AssertionDemo {

    @Test
    public void hardAssertion() {
        Assert.assertEquals("Dashboard", "Dashboard", "Title mismatch");
        Assert.assertTrue(5 > 10, "Value check failed");     // test stops here
        System.out.println("This line never runs");
    }

    @Test
    public void softAssertion() {
        SoftAssert soft = new SoftAssert();

        soft.assertEquals("Asha", "Asha R", "Name mismatch");      // recorded, continues
        soft.assertEquals("asha@test.com", "asha@test.com");
        soft.assertTrue(false, "Phone number is missing");         // recorded, continues
        System.out.println("All checks executed");

        soft.assertAll();        // reports both failures; must be called
    }
}

